'use strict';
// The route workspace reuses customers, invoice rows, the compact picker and printing.
const routeIsWorker=()=>!!CO?.routeRole&&CO.routeRole!=='route_supervisor';
const routeIsManager=()=>!!CO&&(CO.owner||CO.routeRole==='route_supervisor'||!CO.routeRole&&isSupervisor());
