 const total=rows.filter(r=>!['Cancelado','Entregado'].includes(r.status)).reduce((n,r)=>n+r.total,0);
 return '<section class="card"><h3>'+ (CO.routeRole==='route_driver'?'Mis entregas de hoy':'Pedidos por día de entrega')+'</h3><p>Pendiente: '+money(r2(total))+'</p>'+notice('Borrador → Enviado (sin reserva de inventario) → Preparado (reserva carga) → En reparto → Entregado y facturado desde Entregar. Una entrega parcial conserva el saldo; Por reprogramar requiere nueva fecha y preparación. Consulta el estado en cada pedido.')+(routeIsManager()?routeBtn('routePrepare','Preparación del día')+' '+routeBtn('routeDefinition','Registrar ruta / zona')+' '+routeBtn('routePolicy','Políticas de crédito y venta sin carga'):'')+(!rows.length?notice('Todavía no hay pedidos de preventa en tu alcance. Los pedidos históricos permanecen disponibles al final de esta pantalla.'):'')+rows.filter(r=>CO.routeRole!=='route_driver'||r.due===today()&&['Preparado','En reparto','Parcial'].includes(r.status)).map(r=>'<article class="route-customer"><h4>'+esc(r.due)+' · '+esc(r.route||'Sin ruta')+' · '+esc(customerById(r.customerId)?.name||r.name)+'</h4><p>'+esc(r.status)+(r.status==='Enviado'&&r.due<today()?' · Atrasado':'')+' · '+money(r.total)+' · '+esc(routeTeam.find(m=>m.id===(r.routeWorkerId||r.operatorId))?.name||'')+'</p><p>'+r.items.map(i=>esc(prod(i.p)?.name||i.name)+' × '+formatQuantity(i.q)+(r.priceLines?.find(l=>l.productId===i.p)?.specialPrice?' · Precio especial'+(r.priceApproval?' autorizado':' pendiente'):'')).join(' · ')+'</p><p>Por entregar: '+(r.remaining||[]).filter(i=>i.q>0).map(i=>esc(prod(i.p)?.name||i.name)+' × '+formatQuantity(i.q)).join(' · ')+'</p><div class="accounting-actions">'+(['Borrador','Enviado','Pendiente de aprobación'].includes(r.status)&&!(r.deliveries||[]).length?routeBtn('routeOrder','Editar',r.id)+routeBtn('routeSend','Enviar',r.id)+routeBtn('routeCancel','Cancelar',r.id):'')+(['En reparto','Parcial'].includes(r.status)?routeBtn('routeDeliver','Entregar y facturar',r.id)+routeBtn('routeNotDelivered','No entregado',r.id):'')+(routeIsManager()&&['Enviado','Por reprogramar','No entregado','Parcial'].includes(r.status)&&!r.reserved?routeBtn('routeReschedule','Reprogramar con motivo',r.id):'')+(routeIsManager()&&r.status==='Preparado'?routeBtn('routeCancel','Cancelar preparación',r.id):'')+(routeIsManager()&&!['Entregado','Cancelado'].includes(r.status)?routeBtn('routeApproveOrder','Revisar crédito y precios',r.id):'')+routeBtn('routeRepeat','Repetir pedido',r.id)+routeBtn('routePrint','Proforma / documentos',r.id)+(routeIsManager()&&!['Cancelado','Entregado'].includes(r.status)?routeBtn('routeAssign','Reasignar entrega',r.id):'')+'</div></article>').join('')+'</section>'+routeLegacyMarkup();
