function routeReturnRows(l){const settlement=routeRows('route-settlement').find(r=>r.loadId===l.id&&r.status==='Aprobada'&&!r.approvalId),bills=S.entries.filter(e=>(l.sales||[]).includes(e.id)),sum=(items,p)=>items.filter(i=>i.p===p).reduce((n,i)=>n+i.q,0);return [...new Set([...(l.items||[]),...(l.remaining||[]),...(settlement?.counts||[])].map(i=>i.p))].map(p=>{const count=settlement?.counts?.find(i=>i.p===p);return {p,out:sum(l.items||[],p),sold:l.routeGoodsPreview?.find(i=>i.p===p)?.sold??sum(bills.filter(e=>!e.routeDeliveryId).flatMap(e=>e.items||[]),p),delivered:l.routeGoodsPreview?.find(i=>i.p===p)?.delivered??sum(bills.filter(e=>e.routeDeliveryId).flatMap(e=>e.items||[]),p),returns:sum((l.customerReturns||[]).flatMap(r=>r.items||[]),p),expected:count?.expected??sum(l.remaining||[],p),q:count?.q??sum(l.remaining||[],p)}})}
function routeReturnTable(l,editable=false,pending){return cmTable(['Producto / unidad','Salió','Vendido','Entregado','Devuelto por clientes','Debe regresar','Regresó','Diferencia'],routeReturnRows(l).map(i=>'<tr><td>'+esc(prod(i.p)?.name||i.p)+' · '+esc(prod(i.p)?.unit||'unidad')+'</td>'+[i.out,i.sold,i.delivered,i.returns,i.expected].map(q=>'<td>'+formatQuantity(q)+'</td>').join('')+'<td>'+(editable?field('count_'+i.p,'Regresó · '+(prod(i.p)?.unit||'unidad'),pending?.counts?.find(c=>c.p===i.p)?.q??i.q,'number','required min="0" max="1000000" step="0.001"'):formatQuantity(i.q))+'</td><td data-route-diff="'+esc(i.p)+'">'+formatQuantity(Math.round((i.q-i.expected)*1000)/1000)+'</td></tr>'))}
function routeCashMarkup(r){return '<p>Efectivo esperado: '+money((r.amountCents||0)/100)+' · Contado: '+money((r.receivedCents||0)/100)+' · Diferencia: '+money((r.differenceCents||0)/100)+'</p><p>Banco / tarjeta: '+money((r.bankCents||0)/100)+' · Crédito otorgado: '+money((r.creditCents||0)/100)+' · Cobros de cuentas: '+money((r.collectionCents||0)/100)+' · Gastos: '+money((r.expenseCents||0)/100)+'</p>'}
function routeSettleForm(id,pending){const l=routeRows('commerce-load').find(l=>l.id===id);if(!l)return;const rows=routeReturnRows(l),cashRows=pending?.cashRows||l.routeCashPreview||[],financial={amountCents:cashRows.reduce((n,r)=>n+r.amountCents,0)};for(const k of ['bankCents','creditCents','collectionCents','expenseCents'])financial[k]=cashRows.reduce((n,r)=>n+(r[k]||0),0);const orders=routeRows('route-order').filter(r=>r.loadId===l.id&&!['Entregado','Cancelado'].includes(r.status)&&r.remaining?.some(i=>i.q>0));const f=modal('Regreso del camión · '+l.name,cmDate()+routeReturnTable(l,true,pending)+notice('0 = no regresó nada de ese producto. Confirma el conteo físico antes de presentar el regreso.')+orders.map(r=>field('pending_'+r.id,'Motivo obligatorio · '+(customerById(r.customerId)?.name||r.name)+' · '+r.status,pending?.orderReasons?.find(x=>x.orderId===r.id)?.reason||'','text','required maxlength="1000"')).join('')+routeMoneyFields('counted','Efectivo contado de operaciones de ruta')+cmReason()+'<section class="card" data-route-final aria-live="polite"></section><label><input type="checkbox" name="returnConfirmed" required> Confirmo el resumen y las cantidades en 0: no regresó nada de esos productos.</label>'+notice('Las diferencias requieren aprobación del supervisor o dueño. El cierre del turno sigue en Mi día.'),async form=>{await operate(pending?'routeApproveSettlement':'routeSettle',{id:l.id,date:v(form,'date'),items:rows.map(i=>({p:i.p,q:routeZeroQuantity(v(form,'count_'+i.p))})),countedCents:Math.round(Number(v(form,'counted'))*100),reason:v(form,'reason'),orderReasons:orders.map(r=>({orderId:r.id,reason:v(form,'pending_'+r.id)})),confirmed:true});view()},pending?'Aprobar liquidación':'Confirmar regreso');if(pending)f.elements.counted.value=pending.receivedCents/100;
 const update=()=>{try{let missing=[],surplus=[];for(const i of rows){const delta=Math.round((routeZeroQuantity(v(f,'count_'+i.p))-i.expected)*1000)/1000,out=f.querySelector('[data-route-diff="'+i.p+'"]');out.textContent=(delta>0?'+':'')+formatQuantity(delta);out.className=delta<0?'route-shortage':delta>0?'route-surplus':'';if(delta)(delta<0?missing:surplus).push(esc(prod(i.p)?.name||i.p)+' '+formatQuantity(Math.abs(delta))+' '+esc(prod(i.p)?.unit||'unidad'));}financial.receivedCents=Math.round(Number(v(f,'counted'))*100);financial.differenceCents=financial.receivedCents-financial.amountCents;f.querySelector('[data-route-final]').innerHTML='<h4>Resumen antes de confirmar</h4>'+routePerformanceMarkup(l)+'<p>Faltantes: '+(missing.join(' · ')||'Ninguno')+'</p><p>Sobrantes: '+(surplus.join(' · ')||'Ninguno')+'</p>'+routeCashMarkup(financial);}catch(e){f.querySelector('[data-route-final]').textContent=e.message}};f.addEventListener('input',update);update();}
function routePerformanceMarkup(l){return '<p>'+routeReturnRows(l).map(i=>esc(prod(i.p)?.name||i.p)+': '+(i.out?Math.round((i.sold+i.delivered)/i.out*1000)/10:0)+'% vendido o entregado').join(' · ')+'</p>'}

