ACT.routeExport=async()=>{const companyId=CO.id,rows=routeReportRows();await loadExportScript('/vendor/xlsx.js?v=cc015130aa8521e7');if(CO.id!==companyId||!permission('rutas'))return;const grid=[['Fecha','Tipo','Documento','Cliente','Ruta','Trabajador','Estado','Total','Efectivo esperado','Contado','Diferencia','Motivo'],...rows.map(r=>[r.date,r.type||r.kind,r.reference||r.name,customerById(r.customerId)?.name||'',r.route||r.zone||'',routeTeam.find(m=>m.id===(r.routeWorkerId||r.operatorId))?.name||r.operatorName||'',r.status||'Emitida',r.total??(r.amountCents||0)/100,(r.amountCents||0)/100,(r.receivedCents||0)/100,(r.differenceCents||0)/100,r.reason||r.note||''])];const book=XLSX.utils.book_new();for(const [name,grid] of routeFieldReportSheets())XLSX.utils.book_append_sheet(book,XLSX.utils.aoa_to_sheet(grid),name);XLSX.utils.book_append_sheet(book,XLSX.utils.aoa_to_sheet(grid),'Rutas');XLSX.utils.book_append_sheet(book,XLSX.utils.aoa_to_sheet([['Fecha','Ruta','Vendedor / entregador','Ventas sin IVA','Ventas con IVA','Notas sin IVA','Notas con IVA','Costo neto vendido','Utilidad bruta'],...routeProfitRows().map(r=>[r.date,r.route||'',routeTeam.find(m=>m.id===r.assignedMemberId)?.name||r.assignedMemberId||'',...['salesNetCents','salesGrossCents','returnsNetCents','returnsGrossCents','costSoldCents','grossProfitCents'].map(k=>r[k]/100)])]),'Utilidad');downloadFile(new Blob([XLSX.write(book,{bookType:'xlsx',type:'array'})],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}),'rutas-'+today()+'.xlsx')};

// An interrupted request keeps its original payload and UUID until the server confirms it.
window.addEventListener('online',async()=>{const pending=pendingCloudOperation;if(!pending||!CO||CO.id!==pending.companyId||operationInFlight)return;try{await operate(pending.operation,pending.body);if(R==='rutas')view()}catch{/* The existing save status retains the reason and the unconfirmed request. */}});
const routesOriginalOperate=operate;
operate=async function(operation,body={}){try{return await routesOriginalOperate(operation,body)}catch(error){if(!navigator.onLine&&pendingCloudOperation&&(['sale',...Object.keys(ACT).filter(k=>k.startsWith('route'))].includes(operation))){setSt('Pendiente de enviar · Mantén esta pestaña abierta hasta recuperar la conexión.');}throw error}};
