const routeOriginalChrome=chrome;
chrome=function(...args){document.body.classList.toggle('route-session',!!CO?.routeRole);return routeOriginalChrome.apply(this,args)};
function routeSalesSummary(rows){
 const entries=rows.filter(r=>['venta','nota-credito'].includes(r.type)),groups=[['Vendedor',e=>routeTeam.find(m=>m.id===(e.routeWorkerId||e.operatorId))?.name||e.operatorName||'Histórico'],['Ruta',e=>e.route||'Sin ruta'],['Cliente',e=>customerById(e.customerId)?.name||e.party||'Sin cliente']];
 let html='<section class="card"><h3>Ventas netas del período por vendedor, ruta, cliente y producto</h3>';
 for(const [label,key]of groups){const map=new Map();for(const e of entries){const name=key(e);map.set(name,(map.get(name)||0)+Math.round(e.total*100)*(e.type==='nota-credito'?-1:1))}html+='<h4>'+label+'</h4>'+cmTable([label,'Venta neta'],[...map].map(([name,cents])=>'<tr><td>'+esc(name)+'</td><td>'+money(cents/100)+'</td></tr>'))}
 const products=new Map();for(const e of entries)for(const i of e.items||[]){const row=products.get(i.p)||{name:i.name||prod(i.p)?.name||i.p,q:0,cents:0};row.q+=i.q*(e.type==='nota-credito'?-1:1);row.cents+=Math.round(routeMath.invoiceTotals([i]).subtotal*100)*(e.type==='nota-credito'?-1:1);products.set(i.p,row)}
 html+='<h4>Producto</h4>'+cmTable(['Producto','Unidades netas','Importe sin IVA'],[...products.values()].map(r=>'<tr><td>'+esc(r.name)+'</td><td>'+formatQuantity(r.q)+'</td><td>'+money(r.cents/100)+'</td></tr>'));
 return html+'</section>';
}
