function routeSettlementMarkup(load){const r=routeRows('route-settlement').find(r=>r.loadId===load.id&&r.status==='Aprobada'&&!r.approvalId);if(!r)return '';return '<h3>Resumen del regreso</h3>'+routeReturnTable(load)+routePerformanceMarkup(load)+routeCashMarkup(r)+((CO.owner||CO.routeRole==='route_supervisor')&&r.costSoldCents!==undefined?'<p>Costo vendido: '+money(r.costSoldCents/100)+' · Utilidad bruta: '+money(r.grossProfitCents/100)+'</p>':'')+'<p>Aprobó: '+esc(r.approvedBy||'')+' · '+esc(r.reason||'')+'</p>'+(r.orderReasons||[]).map(x=>'<p>'+esc(routeOrder(x.orderId)?.name||'Pedido')+' · '+esc(x.reason)+'</p>').join('');}

function routeProfitRows(){return routeReportRows().filter(r=>r.kind==='route-settlement'&&r.status==='Aprobada'&&!r.approvalId&&r.grossProfitCents!==undefined)}
function routeProfitMarkup(){if(!CO.owner&&CO.routeRole!=='route_supervisor')return '';return '<section class="card"><h3>Utilidad por ruta y vendedor del período</h3>'+notice('Liquidaciones aprobadas en las fechas seleccionadas. Costo histórico registrado, incluido PEPS. Las liquidaciones anteriores sin estos datos no se recalculan.')+cmTable(['Fecha','Ruta','Vendedor / entregador','Ventas sin IVA','Ventas con IVA','Notas sin IVA','Notas con IVA','Costo neto vendido','Utilidad bruta'],routeProfitRows().map(r=>'<tr><td>'+esc(r.date)+'</td><td>'+esc(r.route||'')+'</td><td>'+esc(routeTeam.find(m=>m.id===r.assignedMemberId)?.name||r.assignedMemberId||'')+'</td>'+['salesNetCents','salesGrossCents','returnsNetCents','returnsGrossCents','costSoldCents','grossProfitCents'].map(k=>'<td>'+money(r[k]/100)+'</td>').join('')+'</tr>'))+'</section>'}

