ACT.routePolicy=()=>{const routes=routeRows('route-definition'),scope=[...(CO.owner?[['','Toda la empresa']]:[]),...routes.map(r=>[r.id,r.name])];if(!scope.length)throw Error('Registra primero una ruta.');const f=modal('Políticas de rutas',cmSelect('scope','Ámbito',scope)+cmSelect('requireCreditApproval','Si el pedido supera el crédito disponible',[['inherit','Heredar de la empresa'],['true','Requerir aprobación del supervisor'],['false','Mantener advertencia']])+cmSelect('allowSaleWithoutLoad','Permitir vender del inventario general cuando no tengo carga',[['inherit','Heredar de la empresa'],['true','Permitido'],['false','Bloqueado']])+cmDate()+cmReason()+notice('Por defecto se bloquea vender sin carga y el crédito conserva la advertencia. La aprobación del pedido no cambia la validación de crédito al facturar.'),cmOp('routePolicy',form=>({id:v(form,'scope'),requireCreditApproval:v(form,'requireCreditApproval')==='inherit'?null:v(form,'requireCreditApproval')==='true',allowSaleWithoutLoad:v(form,'allowSaleWithoutLoad')==='inherit'?null:v(form,'allowSaleWithoutLoad')==='true',reason:v(form,'reason')})));const update=()=>{const id=v(f,'scope'),p=id?routes.find(r=>r.id===id)?.routePolicy||{}:S.cfg.routePolicy||{};for(const key of ['requireCreditApproval','allowSaleWithoutLoad']){f.elements[key].querySelector('[value=inherit]').disabled=!id;f.elements[key].value=p[key]===undefined?(id?'inherit':'false'):String(p[key])}};f.elements.scope.addEventListener('change',update);update()};
