function routeBindPhoto(f){
 f.querySelector('.mb').insertAdjacentHTML('beforeend','<label>Foto de entrega (opcional, hasta 1 MB después de comprimir)<input type="file" accept="image/jpeg,image/png,image/webp" data-route-photo></label><p data-route-photo-status role="status"></p>');
 f.querySelector('[data-route-photo]').onchange=async e=>{const out=f.querySelector('[data-route-photo-status]');delete f.routePhoto;const file=e.target.files[0];if(!file){out.textContent='Sin foto de entrega.';return}e.target.disabled=true;f.routePhotoPending=true;out.textContent='Comprimiendo foto…';let bitmap;try{if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>20*1048576)throw Error('Selecciona JPG, PNG o WebP de hasta 20 MB.');bitmap=await createImageBitmap(file);const scale=Math.min(1,1600/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/jpeg',0.75));if(!blob||blob.size>1048576)throw Error('La foto comprimida supera 1 MB. Elige una imagen más pequeña.');const content=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(blob)});f.routePhoto={content,type:'image/jpeg',name:'entrega.jpg'};out.textContent='Foto comprimida lista para enviar con la entrega.';}catch(error){e.target.value='';out.textContent=error.message||'No se pudo comprimir la foto.';}finally{bitmap?.close();e.target.disabled=false;f.routePhotoPending=false}};
}
function routeFieldReportSheets(){
 const records=routeReportRows(),from=routeFilters.from||records.map(r=>r.date).sort()[0]||today(),to=routeFilters.to||today(),days=Math.max(0,Math.floor((Date.parse(to)-Date.parse(from))/86400000)+1);
 const clients=S.customers.filter(c=>(!routeFilters.customer||c.id===routeFilters.customer)&&(!routeFilters.zone||c.routeZone===routeFilters.zone)&&(!routeFilters.worker||c.sellerId===routeFilters.worker));
 const scheduled=c=>{const first=new Date(from+'T00:00:00Z').getUTCDay();return [...new Set(c.visitDays||[])].reduce((n,d)=>n+Math.floor(days/7)+Number((d-first+7)%7<days%7),0)};
 const visits=[['Cliente','Ruta','Vendedor','Programadas (agenda actual)','Realizadas','Sin compra','No visitado'],...clients.map(c=>{const rows=records.filter(r=>r.kind==='commerce-visit'&&r.customerId===c.id);return [c.name,c.routeZone||'',routeTeam.find(m=>m.id===c.sellerId)?.name||c.seller||'',scheduled(c),...['Realizada','Sin compra','No visitado'].map(result=>rows.filter(r=>r.result===result).length)]})];
 const goals=[['Ruta','Vendedor / entregador','Venta neta sin IVA','Meta diaria','Días del período','Meta del período','Cumplimiento %']];
 for(const def of routeRows('route-definition').filter(d=>!routeFilters.zone||d.route===routeFilters.zone)){const sales=records.filter(r=>['venta','nota-credito'].includes(r.type)&&r.route===def.route),workers=[...new Set([...sales.map(r=>r.routeWorkerId||r.operatorId||''),...(def.workerTargets||[]).map(t=>t.memberId)])];for(const id of ['',...workers]){if(routeFilters.worker&&id!==routeFilters.worker)continue;const net=sales.filter(r=>!id||(r.routeWorkerId||r.operatorId||'')===id).reduce((n,e)=>n+(e.type==='nota-credito'?-1:1)*Math.round((e.subtotal||0)*100),0),daily=id?def.workerTargets?.find(t=>t.memberId===id)?.targetCents:def.targetCents,goal=(daily||0)*days;goals.push([def.route,id?routeTeam.find(m=>m.id===id)?.name||id:'Toda la ruta',net/100,daily===undefined?'Sin configurar':daily/100,days,daily===undefined?'Sin configurar':goal/100,goal?Math.round(net/goal*10000)/100:0])}}
 const attempts=records.filter(r=>r.kind==='route-delivery'),failures=attempts.filter(r=>r.status==='No entregado'),rates=[['Cliente','Motivo','No entregas','Intentos del cliente','Tasa %'],...clients.flatMap(c=>[...new Set(failures.filter(r=>r.customerId===c.id).map(r=>r.reason))].map(reason=>{const count=failures.filter(r=>r.customerId===c.id&&r.reason===reason).length,total=attempts.filter(r=>r.customerId===c.id).length;return [c.name,reason,count,total,total?Math.round(count/total*10000)/100:0]}))];
 const late=[['Pedido','Cliente','Ruta','Entrega prevista','Estado','Días de atraso'],...records.filter(r=>r.kind==='route-order'&&['Enviado','Por reprogramar'].includes(r.status)&&r.due<today()).map(r=>[r.name,customerById(r.customerId)?.name||'',r.route,r.due,r.status,Math.floor((Date.parse(today())-Date.parse(r.due))/86400000)])];
 return [['Visitas',visits],['Metas',goals],['No entrega',rates],['Atrasados',late]];
}
