// Durable outbox: no invoices, collections, deliveries or accounting snapshots.
let routeQueueBusy=false,routeQueueTimer=null,routeQueueRows=[],routeQueueResults=[],routeQueueFailures=0;
const routeQueueModule=()=>import('/route-queue.mjs?v=8b47246b98741dd4');
const routeOnlineOperate=operate;
operate=async function(operation,body={}){
 if(routeQueueBusy)throw Error('Espera a que termine el envío de pedidos y visitas.');
 if(!['routeOrder','routeVisit'].includes(operation))return routeOnlineOperate(operation,body);
 if(!permission('rutas',true)||!CO?.branchId)throw Error('No tienes permiso para registrar pedidos o visitas en esta sucursal.');
 const identity=JSON.stringify([U?.email,CO.id,CO.branchId,CO.memberId]);
 const q=await routeQueueModule();if(identity!==JSON.stringify([U?.email,CO?.id,CO?.branchId,CO?.memberId]))throw Error('La sesión o sucursal cambió. Revisa el formulario antes de guardar.');
 const scope=q.queueScope(U,CO),form=document.querySelector('#modal form');
 if(form?.routeQueueOrderId&&operation==='routeOrder')body={...body,id:form.routeQueueOrderId};
 const payload={...q.queuePayload(operation,body,crypto.randomUUID()),branchId:CO.branchId},row={operationId:payload.operationId,scope,companyId:CO.id,branchId:CO.branchId,memberId:CO.memberId||'',email:U.email,payload,createdAt:new Date().toISOString(),status:'pending',message:'Pendiente de enviar'};
 if(form?.routeQueueCorrection)await q.replaceRejected(form.routeQueueCorrection,row);else await q.savePending(row);
 setSt('Guardado en la cola del dispositivo · pendiente de confirmación del servidor.');await routeQueueRefresh();routeQueueSchedule(0);return {queued:true,id:payload.id||payload.operationId};
};
function routeQueueSchedule(delay=1500){clearTimeout(routeQueueTimer);routeQueueTimer=setTimeout(()=>routeQueueSend().catch(()=>{}),delay)}
async function routeQueueRefresh(){
 if(!U?.email||!CO?.branchId)return;try{const q=await routeQueueModule();routeQueueRows=await q.pendingFor(q.queueScope(U,CO));const host=document.querySelector('[data-route-outbox]');if(host)host.innerHTML=routeQueueMarkup();}catch(error){setSt(error.message)}
}
function routeQueueMarkup(){return '<section class="card"><h3>Pedidos y visitas sin sincronizar · '+routeQueueRows.length+'</h3>'+notice('Solo pedidos de preventa y visitas; no incluye facturas. Guardado en este dispositivo no significa aceptado por el servidor. Conserva este navegador y su almacenamiento hasta confirmar el envío.')+routeBtn('routeQueueRetry','Reintentar envíos')+routeQueueRows.map(r=>'<article class="route-customer"><p>'+esc(r.payload.operation==='routeOrder'?'Pedido de preventa':'Visita')+' · '+esc(customerById(r.payload.customerId)?.name||r.payload.customerId)+' · '+esc(r.createdAt)+'</p><p role="status">'+esc(r.message)+'</p>'+(r.status==='rejected'?routeBtn('routeQueueCorrect','Corregir',r.operationId):'')+'</article>').join('')+routeQueueResults.map(message=>'<p role="status">'+esc(message)+'</p>').join('')+'</section>'}
async function routeQueueSend(){
 if(routeQueueBusy||!navigator.onLine||!U?.email||!CO?.branchId||sessionExpired)return;
 if(operationInFlight||pendingCloudOperation||saving){routeQueueSchedule(3000);return}
 if(!permission('rutas',true))return;
 routeQueueBusy=true;let retry=false;
 try{
  if(!await flush())return;
  const q=await routeQueueModule(),scope=q.queueScope(U,CO),companyId=CO.id,rows=await q.pendingFor(scope);
  for(const row of rows){
   if(row.status==='rejected')continue;
   if(!navigator.onLine||!CO||q.queueScope(U,CO)!==scope||sessionExpired)break;
   // Never change payload or operationId; only refresh the revision envelope.
   let acknowledged=false,revision=REV;
   for(let attempt=0;attempt<3;attempt++)try{
    q.validateQueueRow(row);
    if(operationInFlight||saving||pendingCloudOperation)throw Error('Hay otra operación en curso.');
    if(!CO||q.queueScope(U,CO)!==scope)break;
    const base=copyCloud(S),result=await api('operations?c='+companyId,'POST',{...row.payload,revision});
    // Persist removal immediately after server acknowledgement, even if a refresh fails.
    await q.removePending(row.operationId);acknowledged=true;routeQueueFailures=0;
    routeQueueResults.unshift((row.payload.operation==='routeOrder'?'Pedido':'Visita')+' confirmado por el servidor · '+row.createdAt);routeQueueResults=routeQueueResults.slice(0,10);
    if(CO&&q.queueScope(U,CO)===scope){const current=result.replayed?await api('data?c='+companyId):result,merged=AcontecSync.apply(current.data,AcontecSync.diff(base,S));REV=current.revision;cloudBase=copyCloud(current.data);if(merged.conflicts.length)cloudConflict={data:current.data,revision:REV};else{S=merged.data;prepareAccounting()}}
    break;
   }catch(error){
    if(acknowledged){routeQueueResults.unshift('Envío confirmado. Recarga la empresa para actualizar su información.');break}
    if(error.status===409&&attempt<2){try{revision=(await api('data?c='+companyId)).revision;continue}catch{retry=true;break}}
    if([400,403,404,413,422].includes(error.status)){row.status='rejected';row.message='Rechazado por el servidor: '+error.message;await q.savePending(row)}
    else{row.message=error.status===401?'La sesión venció. Ingresa de nuevo para enviar.':error.status===409?'La empresa cambió. Se reintentará conservando el pedido original.':'Sin confirmación del servidor. Se conserva para reintentar.';await q.savePending(row);retry=error.status!==401;if(error.status===401)sessionExpired=true;}
    break;
   }
   if(retry||sessionExpired)break;
  }
 }catch(error){setSt('Cola pendiente · '+error.message);retry=true}
 finally{routeQueueBusy=false;await routeQueueRefresh();if(R==='rutas')routeRender();if(retry&&navigator.onLine&&!sessionExpired&&routeQueueFailures++<5)routeQueueSchedule(Math.min(60000,3000*2**routeQueueFailures))}
}
const routeQueueRender=routeRender;
routeRender=function(){routeQueueRender();const host=document.querySelector('.route-workspace');if(host){host.insertAdjacentHTML('afterbegin','<div data-route-outbox>'+routeQueueMarkup()+'</div>');routeQueueRefresh()}};
READ_ACTIONS.add('routeQueueRetry');routeReadActions.push('routeQueueRetry');
ACT.routeQueueRetry=()=>{routeQueueFailures=0;routeQueueSchedule(0);routeQueueRefresh()};
ACT.routeQueueCorrect=async d=>{
 const row=routeQueueRows.find(r=>r.operationId===d.id&&r.status==='rejected');if(!row)return;const p=row.payload;
 if(p.operation==='routeOrder')ACT.routeOrder({id:routeOrder(p.id)?p.id:p.customerId});else ACT.routeVisit({id:p.customerId});
 const f=document.querySelector('#modal form');if(!f)return;f.routeQueueCorrection=row.operationId;f.routeQueueOrderId=p.id;
 for(const key of ['customerId','date','due','status','payment','note','result','reason'])if(f.elements[key]&&p[key]!==undefined)f.elements[key].value=p[key];
 if(p.location)f.routeLocation=structuredClone(p.location);if(p.items)await routeInitDocument(f,p.items,'order');
 f.querySelector('.mb').insertAdjacentHTML('afterbegin',notice(row.message+' Al guardar se crea un nuevo intento con otro identificador. El original rechazado se sustituye solo después de guardar la corrección en el dispositivo.'));
};
const routeQueueOpenCompany=openCompany;
openCompany=async function(...args){routeQueueRows=[];routeQueueResults=[];routeQueueFailures=0;routeTeam=[];const result=await routeQueueOpenCompany(...args);await routeQueueRefresh();routeQueueSchedule(0);return result};
window.addEventListener('online',async()=>{routeQueueFailures=0;try{if((!U||!CO)&&!sessionExpired){const q=await routeQueueModule();if((await q.allPending()).length)await boot()}}catch{}routeQueueSchedule(0)});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')routeQueueSchedule(0)});
const routeQueueLogout=ACT.logout;
ACT.logout=async(...args)=>{
 try{const q=await routeQueueModule(),pending=(await q.allPending()).filter(r=>r.email===U?.email);if(pending.length&&!confirm('Hay '+pending.length+' pedidos o visitas pendientes en este dispositivo. Al salir se conservan y solo se envían al volver a ingresar con el mismo usuario, empresa y sucursal. ¿Cerrar sesión sin enviarlos?'))return;}
 catch{alert('No se pudo comprobar la cola del dispositivo. Reintenta antes de cerrar sesión.');return}
 if(routeQueueBusy){alert('Espera a que termine el envío antes de cerrar sesión.');return}clearTimeout(routeQueueTimer);return routeQueueLogout(...args);
};

if(CO?.id)routeQueueSchedule(0);
